css:
label {
  transform: scale(1); /* Reduced size */
  display: block;
  width: 100px; /* Smaller width */
  height: 50px; /* Smaller height */
  border-radius: 25px;
  background: linear-gradient(to bottom, #9e9e9e 30%, #f4f4f4);
  box-shadow:
    0 1px 0 0 #fff,
    0 -1px 0 0 #969494;
  position: relative;
  -webkit-tap-highlight-color: rgba(255, 255, 255, 0);
}

label input {
  display: none;
}

label div {
  display: block;
  width: 80px; /* Reduced width */
  height: 30px; /* Reduced height */
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  background: linear-gradient(to bottom, #8b8c8e 20%, #f4f4f4);
  border-radius: 15px;
  transition: 0.2s;
}

label div:after {
  content: "";
  position: absolute;
  display: block;
  height: 28px; /* Reduced height */
  width: 78px; /* Reduced width */
  left: 1px;
  top: 1px;
  border-radius: 14px;
  background: #828080;
  box-shadow: inset 0 0 15px 0 rgba(0, 0, 0, 0.8);
  transition: 0.2s;
}

label i {
  display: block;
  width: 40px; /* Reduced size */
  height: 40px; /* Reduced size */
  position: absolute;
  background: linear-gradient(to top, #9e9e9e 20%, #f4f4f4);
  border-radius: 50%;
  box-shadow: 0 3px 5px 0 rgba(0, 0, 0, 0.7);
  top: 5px;
  left: 5px;
  transition: 0.25s;
}

label i:after {
  content: "";
  position: absolute;
  display: block;
  width: 34px; /* Reduced size */
  height: 34px; /* Reduced size */
  left: 3px;
  top: 3px;
  border-radius: 50%;
  background: #d5d4d4;
  z-index: 1;
}

label input:checked ~ i {
  top: 5px;
  left: 54px; /* Adjusted to fit new size */
}

label input:checked + div:after {
  background: #0f0; /* Green glow */
  box-shadow: inset 0 0 15px 0 rgba(0, 0, 0, 0.6);
}

label input:checked + div > .off {
  color: transparent;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0);
}

label input:checked + div > .on {
  color: hsl(24, 2%, 49%);
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.3);
}

label input:not(:checked) + div:after {
  background: #f00; /* Red glow */
  box-shadow: inset 0 0 15px 0 rgba(0, 0, 0, 0.6);
}

label input:not(:checked) + div > .on {
  color: transparent;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0);
}

label input:not(:checked) + div > .off {
  color: #444;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.2);
}

label:after {
  content: "";
  position: absolute;
  display: block;
  width: 102px; /* Adjusted to fit new size */
  height: 52px; /* Adjusted to fit new size */
  border-radius: 26px;
  top: -1px;
  left: -1px;
  z-index: -1;
  background: linear-gradient(to bottom, #969494, #fff);
}

label:hover {
  cursor: pointer;
}

label:focus,
label:active {
  outline: 0;
}

.on,
.off {
  text-transform: uppercase;
  position: absolute;
  left: 12px; /* Adjusted for smaller size */
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.8em; /* Smaller font size */
  font-weight: 600;
  z-index: 2;
  letter-spacing: 1px;
  transition: 0.25s;
}

.on {
  color: transparent;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0);
}

.off {
  left: initial;
  right: 12px; /* Adjusted for smaller size */
  color: hsl(24, 2%, 49%);
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.2);
}

@keyframes switchOn {
  0% {
    background-color: #f00;
    box-shadow: 0 0 5px rgba(255, 0, 0, 0.5);
  }
  100% {
    background-color: #0f0;
    box-shadow: 0 0 5px rgba(0, 255, 0, 0.5);
  }
}

@keyframes switchOff {
  0% {
    background-color: #0f0;
    box-shadow: 0 0 5px rgba(0, 255, 0, 0.5);
  }
  100% {
    background-color: #f00;
    box-shadow: 0 0 5px rgba(255, 0, 0, 0.5);
  }
}

label input:checked + div:after {
  animation: switchOn 0.5s ease-in-out forwards;
}

label input:not(:checked) + div:after {
  animation: switchOff 0.5s ease-in-out forwards;
}
